INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (597, 1, '전체 건강 판정', '`/tmp/smart_hdd.log` 는 HDD 에 `smartctl -a` 를 실행한 결과입니다. `overall-health self-assessment test result:` 줄은 장치가 스스로 내린 전체 판정(PASSED 또는 FAILED)입니다. 이 **판정 값**을 `/tmp/overall.txt` 에 저장하세요. (값만)', '판정 줄의 마지막 단어입니다.', 'cat /tmp/smart_hdd.log
grep ''overall-health'' /tmp/smart_hdd.log | awk ''{print $NF}'' > /tmp/overall.txt
cat /tmp/overall.txt

# PASSED 여도 안심하면 안 된다. 이 판정은 속성이 한계(THRESH)를 넘었을 때만 FAILED 가 되어 징후가 나타나기 전에는 통과로 나온다. 개별 속성의 추세를 함께 본다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/smart_hdd.log <<''EOF''\\n=== START OF READ SMART DATA SECTION ===\\nSMART overall-health self-assessment test result: PASSED\\n\\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\\n  5 Reallocated_Sector_Ct   0x0033   098   098   010    Pre-fail  Always       -       24\\n  9 Power_On_Hours          0x0032   071   071   000    Old_age   Always       -       25300\\n194 Temperature_Celsius     0x0022   060   048   000    Old_age   Always       -       40\\n197 Current_Pending_Sector  0x0012   100   100   000    Old_age   Always       -       8\\n198 Offline_Uncorrectable   0x0010   100   100   000    Old_age   Offline      -       0\\n199 UDMA_CRC_Error_Count    0x003e   200   200   000    Old_age   Always       -       0\\nEOF\\ncat > /tmp/smart_nvme.log <<''EOF''\\nSMART/Health Information (NVMe Log 0x02)\\nCritical Warning:                   0x00\\nTemperature:                        43 Celsius\\nAvailable Spare:                    100%\\nAvailable Spare Threshold:          10%\\nPercentage Used:                    87%\\nData Units Written:                 120,000,000 [61.4 TB]\\nMedia and Data Integrity Errors:    0\\nError Information Log Entries:      3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/overall.txt)\\" = PASSED ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "PASSED 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/overall.txt)\\" = PASSED ]"]}]', '[{"title": "smartmontools 문서", "url": "https://www.smartmontools.org/wiki/TocDoc"}, {"title": "smartctl 매뉴얼", "url": "https://linux.die.net/man/8/smartctl"}]'),
  (597, 2, '재할당 섹터 수', '`Reallocated_Sector_Ct`(재할당 섹터 수)는 불량이 난 섹터를 예비 영역으로 옮긴 횟수입니다. 이 속성의 **원시값(`RAW_VALUE`, 맨 끝 칸)** 을 숫자만 `/tmp/realloc.txt` 에 저장하세요.', '속성 이름이 있는 줄의 마지막 칸이 원시값입니다.', 'grep Reallocated_Sector_Ct /tmp/smart_hdd.log | awk ''{print $NF}'' > /tmp/realloc.txt
cat /tmp/realloc.txt

# 0 이 정상이고 0 이 아니면 이미 불량 섹터가 생겼다는 신호다. 숫자가 계속 늘어나면 교체를 준비한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/smart_hdd.log <<''EOF''\\n=== START OF READ SMART DATA SECTION ===\\nSMART overall-health self-assessment test result: PASSED\\n\\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\\n  5 Reallocated_Sector_Ct   0x0033   098   098   010    Pre-fail  Always       -       24\\n  9 Power_On_Hours          0x0032   071   071   000    Old_age   Always       -       25300\\n194 Temperature_Celsius     0x0022   060   048   000    Old_age   Always       -       40\\n197 Current_Pending_Sector  0x0012   100   100   000    Old_age   Always       -       8\\n198 Offline_Uncorrectable   0x0010   100   100   000    Old_age   Offline      -       0\\n199 UDMA_CRC_Error_Count    0x003e   200   200   000    Old_age   Always       -       0\\nEOF\\ncat > /tmp/smart_nvme.log <<''EOF''\\nSMART/Health Information (NVMe Log 0x02)\\nCritical Warning:                   0x00\\nTemperature:                        43 Celsius\\nAvailable Spare:                    100%\\nAvailable Spare Threshold:          10%\\nPercentage Used:                    87%\\nData Units Written:                 120,000,000 [61.4 TB]\\nMedia and Data Integrity Errors:    0\\nError Information Log Entries:      3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/realloc.txt)\\" = 24 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "24 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/realloc.txt)\\" = 24 ]"]}]', '[{"title": "smartmontools 문서", "url": "https://www.smartmontools.org/wiki/TocDoc"}, {"title": "smartctl 매뉴얼", "url": "https://linux.die.net/man/8/smartctl"}]'),
  (597, 3, '대기 섹터 수', '`Current_Pending_Sector`(대기 섹터)는 읽기에 실패해 재할당을 기다리는 섹터 수입니다. **원시값**을 숫자만 `/tmp/pending.txt` 에 저장하세요.', '재할당 섹터와 같은 방식으로 속성 이름 줄의 끝 칸을 뽑으세요.', 'grep Current_Pending_Sector /tmp/smart_hdd.log | awk ''{print $NF}'' > /tmp/pending.txt
cat /tmp/pending.txt

# 대기 섹터가 0 보다 크면 곧 불량이 될 수 있어 위험하다. 이 섹터에 다시 쓰면 재할당되어 재할당 수로 옮겨 가거나 회복되기도 한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/smart_hdd.log <<''EOF''\\n=== START OF READ SMART DATA SECTION ===\\nSMART overall-health self-assessment test result: PASSED\\n\\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\\n  5 Reallocated_Sector_Ct   0x0033   098   098   010    Pre-fail  Always       -       24\\n  9 Power_On_Hours          0x0032   071   071   000    Old_age   Always       -       25300\\n194 Temperature_Celsius     0x0022   060   048   000    Old_age   Always       -       40\\n197 Current_Pending_Sector  0x0012   100   100   000    Old_age   Always       -       8\\n198 Offline_Uncorrectable   0x0010   100   100   000    Old_age   Offline      -       0\\n199 UDMA_CRC_Error_Count    0x003e   200   200   000    Old_age   Always       -       0\\nEOF\\ncat > /tmp/smart_nvme.log <<''EOF''\\nSMART/Health Information (NVMe Log 0x02)\\nCritical Warning:                   0x00\\nTemperature:                        43 Celsius\\nAvailable Spare:                    100%\\nAvailable Spare Threshold:          10%\\nPercentage Used:                    87%\\nData Units Written:                 120,000,000 [61.4 TB]\\nMedia and Data Integrity Errors:    0\\nError Information Log Entries:      3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/pending.txt)\\" = 8 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "8 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/pending.txt)\\" = 8 ]"]}]', '[{"title": "smartmontools 문서", "url": "https://www.smartmontools.org/wiki/TocDoc"}, {"title": "smartctl 매뉴얼", "url": "https://linux.die.net/man/8/smartctl"}]'),
  (597, 4, '가동 시간을 연으로', '`Power_On_Hours` 의 원시값은 디스크가 켜져 있던 **누적 시간**입니다. 이를 **연 단위로 소수점 이하를 버린 정수**(1년 = 8760 시간)로 계산해 `/tmp/years.txt` 에 저장하세요.', '원시값을 뽑아 쉘 정수 산술로 8760 으로 나누세요.', 'H=$(grep Power_On_Hours /tmp/smart_hdd.log | awk ''{print $NF}'')
echo $((H / 8760)) > /tmp/years.txt
cat /tmp/years.txt

# 25300 시간은 약 2.9 년이다. 가동 시간 자체보다 불량 섹터 증가 같은 속성의 변화를 함께 본다. HDD 는 보통 3~5 년 사용 뒤 교체를 계획한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/smart_hdd.log <<''EOF''\\n=== START OF READ SMART DATA SECTION ===\\nSMART overall-health self-assessment test result: PASSED\\n\\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\\n  5 Reallocated_Sector_Ct   0x0033   098   098   010    Pre-fail  Always       -       24\\n  9 Power_On_Hours          0x0032   071   071   000    Old_age   Always       -       25300\\n194 Temperature_Celsius     0x0022   060   048   000    Old_age   Always       -       40\\n197 Current_Pending_Sector  0x0012   100   100   000    Old_age   Always       -       8\\n198 Offline_Uncorrectable   0x0010   100   100   000    Old_age   Offline      -       0\\n199 UDMA_CRC_Error_Count    0x003e   200   200   000    Old_age   Always       -       0\\nEOF\\ncat > /tmp/smart_nvme.log <<''EOF''\\nSMART/Health Information (NVMe Log 0x02)\\nCritical Warning:                   0x00\\nTemperature:                        43 Celsius\\nAvailable Spare:                    100%\\nAvailable Spare Threshold:          10%\\nPercentage Used:                    87%\\nData Units Written:                 120,000,000 [61.4 TB]\\nMedia and Data Integrity Errors:    0\\nError Information Log Entries:      3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/years.txt)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "2 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/years.txt)\\" = 2 ]"]}]', '[{"title": "smartmontools 문서", "url": "https://www.smartmontools.org/wiki/TocDoc"}, {"title": "smartctl 매뉴얼", "url": "https://linux.die.net/man/8/smartctl"}]'),
  (597, 5, 'NVMe 의 사용률', '`/tmp/smart_nvme.log` 는 NVMe SSD 의 건강 정보입니다. `Percentage Used` 는 제조사가 예상한 **수명 대비 사용한 비율**입니다. 이 값을 `%` 없이 숫자만 `/tmp/used.txt` 에 저장하세요.', '`Percentage Used` 줄의 마지막 칸에서 `%` 를 떼세요.', 'cat /tmp/smart_nvme.log
grep ''Percentage Used'' /tmp/smart_nvme.log | awk ''{print $NF}'' | tr -d ''%'' > /tmp/used.txt
cat /tmp/used.txt

# 87% 는 수명의 대부분을 썼다는 뜻이다. 100% 를 넘어도 바로 고장나지는 않지만 보증과 안정성이 끝나는 구간이라 교체를 준비한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/smart_hdd.log <<''EOF''\\n=== START OF READ SMART DATA SECTION ===\\nSMART overall-health self-assessment test result: PASSED\\n\\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\\n  5 Reallocated_Sector_Ct   0x0033   098   098   010    Pre-fail  Always       -       24\\n  9 Power_On_Hours          0x0032   071   071   000    Old_age   Always       -       25300\\n194 Temperature_Celsius     0x0022   060   048   000    Old_age   Always       -       40\\n197 Current_Pending_Sector  0x0012   100   100   000    Old_age   Always       -       8\\n198 Offline_Uncorrectable   0x0010   100   100   000    Old_age   Offline      -       0\\n199 UDMA_CRC_Error_Count    0x003e   200   200   000    Old_age   Always       -       0\\nEOF\\ncat > /tmp/smart_nvme.log <<''EOF''\\nSMART/Health Information (NVMe Log 0x02)\\nCritical Warning:                   0x00\\nTemperature:                        43 Celsius\\nAvailable Spare:                    100%\\nAvailable Spare Threshold:          10%\\nPercentage Used:                    87%\\nData Units Written:                 120,000,000 [61.4 TB]\\nMedia and Data Integrity Errors:    0\\nError Information Log Entries:      3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/used.txt)\\" = 87 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "87 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/used.txt)\\" = 87 ]"]}]', '[{"title": "smartmontools 문서", "url": "https://www.smartmontools.org/wiki/TocDoc"}, {"title": "smartctl 매뉴얼", "url": "https://linux.die.net/man/8/smartctl"}]'),
  (597, 6, '여분 용량 상태', '`Available Spare`(남은 예비 셀 비율)가 `Available Spare Threshold`(경고 기준) **밑으로 내려가면** 위험합니다. `/tmp/smart_nvme.log` 에서 두 값을 비교해, 여분이 기준보다 높으면 `ok`, 같거나 낮으면 `low` 한 단어를 `/tmp/spare.txt` 에 저장하세요.', '두 값을 뽑아 비교하세요.', 'grep -E ''Available Spare'' /tmp/smart_nvme.log
S=$(grep ''^Available Spare:'' /tmp/smart_nvme.log | awk ''{print $3}'' | tr -d ''%'')
T=$(grep ''Threshold'' /tmp/smart_nvme.log | awk ''{print $4}'' | tr -d ''%'')
if [ "$S" -gt "$T" ]; then echo ok > /tmp/spare.txt; else echo low > /tmp/spare.txt; fi
cat /tmp/spare.txt

# 여분 셀이 줄어 기준 아래가 되면 장치가 위험 경고를 내고 곧 읽기 전용이 될 수 있다. 사용률(Percentage Used)과 함께 본다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/smart_hdd.log <<''EOF''\\n=== START OF READ SMART DATA SECTION ===\\nSMART overall-health self-assessment test result: PASSED\\n\\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\\n  5 Reallocated_Sector_Ct   0x0033   098   098   010    Pre-fail  Always       -       24\\n  9 Power_On_Hours          0x0032   071   071   000    Old_age   Always       -       25300\\n194 Temperature_Celsius     0x0022   060   048   000    Old_age   Always       -       40\\n197 Current_Pending_Sector  0x0012   100   100   000    Old_age   Always       -       8\\n198 Offline_Uncorrectable   0x0010   100   100   000    Old_age   Offline      -       0\\n199 UDMA_CRC_Error_Count    0x003e   200   200   000    Old_age   Always       -       0\\nEOF\\ncat > /tmp/smart_nvme.log <<''EOF''\\nSMART/Health Information (NVMe Log 0x02)\\nCritical Warning:                   0x00\\nTemperature:                        43 Celsius\\nAvailable Spare:                    100%\\nAvailable Spare Threshold:          10%\\nPercentage Used:                    87%\\nData Units Written:                 120,000,000 [61.4 TB]\\nMedia and Data Integrity Errors:    0\\nError Information Log Entries:      3\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/spare.txt)\\" = ok ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ok 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/spare.txt)\\" = ok ]"]}]', '[{"title": "smartmontools 문서", "url": "https://www.smartmontools.org/wiki/TocDoc"}, {"title": "smartctl 매뉴얼", "url": "https://linux.die.net/man/8/smartctl"}]'),
  (597, 7, '재할당 섹터가 늘어날 때', 'HDD 의 `Reallocated_Sector_Ct` 가 지난주 4 에서 이번 주 24 로 늘었습니다. 가장 알맞은 판단은?', '값의 크기보다 변화 추세가 중요합니다.', NULL, NULL, '[]', 'choice', '["원시값이 24 로 낮아 정상이므로 그대로 둔다", "재할당이 늘면 디스크가 좋아지고 있다는 뜻이다", "불량이 늘어나는 신호이니 백업 확인 후 교체를 준비한다", "SMART 값은 참고할 수 없는 값이라 무시한다"]', 2, '재할당 섹터가 계속 늘면 표면에 불량이 퍼지고 있다는 신호입니다. 절대값이 작아도 증가 추세가 위험하므로 백업을 확인하고 교체를 준비합니다. 값 0 이 정상입니다.', NULL, NULL, NULL, NULL),
  (597, 8, 'VALUE 와 RAW_VALUE', 'SMART 속성 표의 `VALUE`(정규화 값)와 `RAW_VALUE`(원시값)에 대한 설명으로 알맞은 것은?', '정규화 값은 제조사가 정한 점수이고 한계와 비교합니다.', NULL, NULL, '[]', 'choice', '["VALUE 는 항상 실제 불량 섹터의 개수와 같다", "VALUE 는 한계 이하면 실패, RAW_VALUE 는 실제 계수", "RAW_VALUE 가 클수록 디스크가 항상 정상이다", "두 값은 의미가 같아서 둘 중 하나는 필요가 없다"]', 1, 'VALUE 는 제조사가 계산해 1~253 범위(높을수록 양호)로 정규화한 점수로 THRESH 이하가 되면 실패입니다. RAW_VALUE 는 실제 횟수·시간 같은 원시 계수라 사람이 읽기에는 원시값 추세가 유용합니다.', NULL, NULL, NULL, NULL),
  (597, 9, 'SMART 만 믿으면 안 되는 이유', 'SMART 전체 판정은 PASSED 인데 디스크가 갑자기 고장나는 경우가 있습니다. 가장 알맞은 설명은?', 'PASSED 판정이 무엇을 보장하고 무엇을 보장하지 않는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["모든 고장을 예고하진 못해 백업과 이중화가 필요하다", "SMART 가 PASSED 면 절대 고장나지 않는다", "SMART 는 SSD 에서만 동작하는 기능이다", "PASSED 판정은 언제나 거짓으로 나오는 값이다"]', 0, '일부 고장(전자 부품 불량, 펌웨어 오류, 갑작스러운 헤드 문제)은 SMART 로 미리 알 수 없습니다. 그래서 SMART 는 보조 징후로 쓰고 백업·이중화·모니터링을 함께 둡니다.', NULL, NULL, NULL, NULL),
  (597, 10, '전체 판정만 보기', '디스크의 **전체 건강 판정(PASSED/FAILED)만** 간단히 보려는 `smartctl` 옵션을 채우세요.', '`smartctl` 옵션은 대소문자를 구분합니다. health 와 관련된 옵션을 고르세요.', NULL, NULL, '[]', 'fill', '["H", "A", "a", "i"]', NULL, '`-H` 는 전체 건강 판정만, `-A` 는 속성 표, `-a` 는 모든 정보, `-i` 는 장치 정보(모델·펌웨어)를 보여 줍니다.', '[0]', 'smartctl -{0} /dev/sda', NULL, NULL),
  (597, 11, '디스크 경고를 받았을 때', '모니터링에서 디스크 하나의 대기 섹터 경고가 올라왔습니다. 안전하게 대응하는 순서로 놓으세요.', '먼저 경고의 심각도를 알아야 하고, 디스크를 바꾸는 일은 마지막입니다.', NULL, NULL, '[]', 'order', '["디스크를 교체하고 재구축·복원이 끝나는지 확인한다", "백업과 복제 상태를 확인하고 필요하면 즉시 백업한다", "`smartctl -A` 로 속성과 추세를 확인한다", "백업이 확보된 뒤, 같은 어레이·LV 에 속한 다른 디스크의 상태도 점검한다"]', NULL, '속성과 추세로 심각도를 판단하고, 데이터 안전(백업)을 확보한 뒤, 같은 그룹의 다른 디스크도 점검하고, 마지막에 교체와 재구축을 진행합니다. 재구축 중에는 다른 디스크의 부하가 커서 미리 상태를 확인해야 합니다.', '[2, 1, 3, 0]', NULL, NULL, NULL);
